/* ============================================
   AVATAR COMPONENT
   User profile image with initials fallback
   ============================================ */

.ds-avatar {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-pill); /* 999px */
  background-color: var(--color-bg-container-secondary);
  flex-shrink: 0;
}

/* ============================================
   SIZES
   ============================================ */

.ds-avatar--sm {
  width: 32px;
  height: 32px;
}

.ds-avatar--md {
  width: 40px;
  height: 40px;
}

.ds-avatar--lg {
  width: 56px;
  height: 56px;
}

/* ============================================
   IMAGE
   ============================================ */

.ds-avatar__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: var(--radius-pill);
}

/* ============================================
   INITIALS FALLBACK
   ============================================ */

.ds-avatar__initials {
  font-family: var(--font-paragraph-emphasis-family);
  font-weight: var(--font-paragraph-emphasis-weight);
  color: var(--color-text-primary);
  line-height: 1;
  user-select: none;
}

.ds-avatar--sm .ds-avatar__initials {
  font-size: 12px; /* ds-allow(typography): initials are sized to the fixed avatar box, not the type ladder, so a type-scale lever cannot overflow them */
}

.ds-avatar--md .ds-avatar__initials {
  font-size: 14px; /* ds-allow(typography): sized to the avatar box, as above */
}

.ds-avatar--lg .ds-avatar__initials {
  font-size: 18px; /* ds-allow(typography): sized to the avatar box, as above */
}

/* ============================================
   FILLS
   Six fills picked by name, each with its own initials colour, so a stack
   of people reads apart. The `--color-avatar-*` tokens own the colours.
   ============================================ */

.ds-avatar--fill-1 {
  background-color: var(--color-avatar-bg-1);
}

.ds-avatar--fill-1 .ds-avatar__initials {
  color: var(--color-avatar-text-1);
}

.ds-avatar--fill-2 {
  background-color: var(--color-avatar-bg-2);
}

.ds-avatar--fill-2 .ds-avatar__initials {
  color: var(--color-avatar-text-2);
}

.ds-avatar--fill-3 {
  background-color: var(--color-avatar-bg-3);
}

.ds-avatar--fill-3 .ds-avatar__initials {
  color: var(--color-avatar-text-3);
}

.ds-avatar--fill-4 {
  background-color: var(--color-avatar-bg-4);
}

.ds-avatar--fill-4 .ds-avatar__initials {
  color: var(--color-avatar-text-4);
}

.ds-avatar--fill-5 {
  background-color: var(--color-avatar-bg-5);
}

.ds-avatar--fill-5 .ds-avatar__initials {
  color: var(--color-avatar-text-5);
}

.ds-avatar--fill-6 {
  background-color: var(--color-avatar-bg-6);
}

.ds-avatar--fill-6 .ds-avatar__initials {
  color: var(--color-avatar-text-6);
}

/* ============================================
   ICON FALLBACK
   ============================================ */

.ds-avatar__icon {
  color: var(--color-icon-secondary);
  line-height: 1;
}

.ds-avatar--sm .ds-avatar__icon {
  --icon-size: var(--icon-size-500);
}

.ds-avatar--md .ds-avatar__icon {
  --icon-size: var(--icon-size-600);
}

.ds-avatar--lg .ds-avatar__icon {
  --icon-size: var(--icon-size-800);
}

/* ============================================
   STATUS INDICATOR
   ============================================ */

.ds-avatar__status {
  position: absolute;
  bottom: 0;
  right: 0;
  border-radius: var(--radius-pill);
  border: 2px solid var(--color-bg-page-primary);
}

.ds-avatar--sm .ds-avatar__status {
  width: 10px;
  height: 10px;
}

.ds-avatar--md .ds-avatar__status {
  width: 12px;
  height: 12px;
}

.ds-avatar--lg .ds-avatar__status {
  width: 14px;
  height: 14px;
}

.ds-avatar__status--online {
  background-color: var(--color-status-positive-border);
}

.ds-avatar__status--away {
  background-color: var(--color-status-warning-border);
}

.ds-avatar__status--offline {
  background-color: var(--color-bg-container-border);
}

.ds-avatar__status--busy {
  background-color: var(--color-status-error-border);
}

'use client';

import React, { useState } from 'react';
import './Avatar.css';
import '../../fonts/material-symbols.css';
import { avatarFill, type AvatarFill } from './avatarFill';

/** Props owned by Avatar itself — everything else falls through to the root span. */
type AvatarOwnProps = {
  /** Image source URL */
  src?: string;
  /** Alt text for the image, also the avatar's accessible name. A passed `aria-label` takes precedence. */
  alt?: string;
  /** User's name — used for initials fallback */
  name?: string;
  /** Avatar size */
  size?: 'sm' | 'md' | 'lg';
  /**
   * Which of the six fills the initials sit on. Picked from the name when
   * unset, so a person keeps one colour everywhere; `neutral` keeps the
   * plain grey. An AvatarGroup
   * sets it on its avatars so neighbours in the stack differ.
   */
  fill?: AvatarFill | 'neutral';
  /** Online status indicator */
  status?: 'online' | 'away' | 'offline' | 'busy';
  /** Accessible name for the status dot. Defaults to the `status` value itself (e.g. "online"). */
  statusLabel?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface AvatarProps
  extends AvatarOwnProps,
    Omit<React.ComponentPropsWithoutRef<'span'>, keyof AvatarOwnProps | 'children'> {}

/**
 * Avatar component for user profile images.
 * Falls back to initials derived from the name prop,
 * or a person icon when neither image nor name is provided.
 * Forwards a ref to the root span and spreads native attributes onto it.
 */
export const Avatar = React.forwardRef<HTMLSpanElement, AvatarProps>(
  (
    {
      src,
      alt,
      name,
      size = 'md',
      fill,
      status,
      statusLabel,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const [imgError, setImgError] = useState(false);

    const baseClass = 'ds-avatar';
    const sizeClass = `${baseClass}--${size}`;

    /* Only initials take a fill: an image covers it, and the generic glyph
       stands for no one in particular, so it stays grey. */
    const fillIndex = name?.trim() && fill !== 'neutral' ? (fill ?? avatarFill(name.trim())) : null;
    const fillClass = fillIndex ? `${baseClass}--fill-${fillIndex}` : '';

    const classes = [baseClass, sizeClass, fillClass, className].filter(Boolean).join(' ');

    const getInitials = (fullName: string): string => {
      const parts = fullName.trim().split(/\s+/);
      if (parts.length === 1) return parts[0][0].toUpperCase();
      return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
    };

    const showImage = src && !imgError;
    const showInitials = !showImage && name;
    const showIcon = !showImage && !name;

    const label = alt || name || 'User avatar';

    return (
      <span aria-label={label} {...rest} ref={ref} className={classes} role="img">
        {showImage && (
          <img
            className={`${baseClass}__image`}
            src={src}
            alt={alt || name || ''}
            onError={() => setImgError(true)}
          />
        )}

        {showInitials && (
          <span className={`${baseClass}__initials`} aria-hidden="true">
            {getInitials(name!)}
          </span>
        )}

        {showIcon && (
          <span
            className={`${baseClass}__icon material-symbols-rounded`}
            aria-hidden="true"
          >
            person
          </span>
        )}

        {status && (
          <span
            className={`${baseClass}__status ${baseClass}__status--${status}`}
            // A bare <span> has no role, and aria-label is prohibited on roles
            // that provide no semantics. role="img" is what this dot actually is.
            role="img"
            aria-label={statusLabel ?? status}
          />
        )}
      </span>
    );
  },
);

Avatar.displayName = 'Avatar';

export type { AvatarFill } from './avatarFill';

/**
 * The fill an initials Avatar takes, apart from the component so a
 * server-rendered AvatarGroup can spread its fills without importing a
 * client module. Internal: the public name is AvatarFill, re-exported from
 * Avatar.
 */

import { hashName } from '../PixelAvatar/pixelInks';

/** One of the six avatar fills, by token number (`--color-avatar-bg-*`). */
export type AvatarFill = 1 | 2 | 3 | 4 | 5 | 6;

/* The fill a name picks for itself. FNV-1a alone leaves its low bits
   clumped on short names (four of six sample names landed on one fill),
   so the hash is run through a 32-bit finaliser before the remainder. */
export const avatarFill = (name: string): AvatarFill => {
  let hash = hashName(name);
  hash ^= hash >>> 16;
  hash = Math.imul(hash, 0x7feb352d);
  hash ^= hash >>> 15;
  hash = Math.imul(hash, 0x846ca68b);
  hash ^= hash >>> 16;
  return (((hash >>> 0) % 6) + 1) as AvatarFill;
};
